let historyChat = [];
const getHistory = (user) =>
  historyChat.filter((message) => (message.user === user || message.to === user) && message.user !== message.to);

const deleteMessage = (user, table, item) => {
  let iterator = 0,
    numToDel;
  console.log("user", user);
  console.log("table", table);
  console.log("item", item);
  historyChat.map((obj, index) => {
    iterator++;
    if (obj.user === user && obj.table === table) {
      if (iterator === item) {
        numToDel = index;
      }
    }
    return obj;
  });
  historyChat.splice(numToDel, 1);
  historyChat.map((e) => {
    console.log("date", e.date);
    console.log("user", e.user);
    console.log("message", e.message);
    console.log("to", e.to);
  });
};

module.exports = { historyChat, getHistory, deleteMessage };

