sourcesContent:
const React = require("react");
const { Link } = require("react-router");
const AnimationCircle = require("./animationCircle.jsx");
const TTable = require("./TTable.jsx");
/*const fD = ReactDOM.findDOMNode;*/

class Menu extends React.Component {
  constructor(props) {
    super(props);
    this.handleBuy = this.handleBuy.bind(this);
    this.state = { menuData: [] };
  }
  handleBuy(event) {
    this.props.route.addToCart(this.props.params.id);
  }
  componentWillMount() {
    let url;
    if (this.props.id) {
      console.log("id", this.props.id);
      console.log("location", this.props.location);
      url = this.props.location;
    } else {
      url = location.origin + "/get_menu/" + this.props.params.id;
    }
    console.log("url", url);
    let { ColumnStruct } = this.props.route;
    fetch(url)
      .then((response) => response.json())
      .then((data) => {
        if (data.length) {
          ColumnStruct("clear");
          let o = Array.from(Object.entries(Array.of(Object.entries(data)).flat()[0][1])).flat()[1][0];
          for (let [k, v] of Object.entries(o)) {
            let obj = {};
            obj[`${k}`] = v;
            ColumnStruct("add", obj);
          }
        }
        this.setState({ menuData: [...data] });
      });
  }
  render() {
    let { src, title } = this.props.route.product[this.props.params.id];
    let { menuData } = this.state;
    if (!menuData.length) {
      return (
        <div className='menuImg'>
          <AnimationCircle />
          {src ? <img src={src} /> : null}
          <p>{title}</p>
        </div>
      );
    }
    let { addToCart, cartItems, ColumnStruct } = this.props.route;
    return (
      <div
        className='wrapper_modal'
        style={{ position: "fixed", top: "24%", width: "80%" }}>
        <div
          className='menuImg'
          style={{ position: "fixed", top: "26%" }}>
          <div
            className='wrapper_menuImg'
            style={{
              display: "flex",
              flexFlow: "row nowrap",
              justifyContent: "space-between",
            }}>
            {src ? (
              <img
                src={src}
                style={{
                  width: "230px",
                  height: "130px",
                  display: "inline-block",
                }}
              />
            ) : null}
            <div
              className='title_menu_caption'
              style={{
                left: "320px",
                height: "40px",
                display: "flex",
                flexFlow: "row wrap",
              }}>
              <p style={{ display: "inline-block" }}>{title}</p>
            </div>
          </div>
        </div>
        <div
          className='wrapper_all_tables'
          style={{
            overflowY: "auto",
            position: "absolute",
            top: "150px",
            width: "91%",
            height: "60vh",
            overflowX: "hidden",
          }}>
          {menuData.map((groupname, i) => {
            let titleGroup = Object.getOwnPropertyNames(groupname)[0];
            return (
              <TTable
                key={i}
                titleGroup={titleGroup}
                ColumnStruct={ColumnStruct}
                groupname={groupname}
                addToCart={addToCart}
                cartItems={cartItems}
              />
            );
          })}
        </div>
      </div>
    );
  }
}

module.exports = Menu;

