sourcesContent:
const React = require("react");
const Modal = require("./modal.jsx");
const TDescribeDishes = require("./TDescribeDishes.jsx");
const { FcCamera } = require("react-icons/fc");

class TDElement extends React.Component {
  constructor(props) {
    super(props);
    this.handlerPopupDesciption = this.handlerPopupDesciption.bind(this);
    this.state = { popupDesciption: null };
    this.mouseLeave = this.mouseLeave.bind(this);
  }
  mouseLeave(event) {
    event.stopPropagation();
    event.preventDefault();
    this.setState({ popupDesciption: false });
  }
  handlerPopupDesciption(target) {
    target.stopPropagation();
    target.preventDefault();
    this.setState({ popupDesciption: true });
  }
  render() {
    let { dataRow, src, addToCart, cartItems } = this.props;
    return (
      <td onClick={this.handlerPopupDesciption}>
        <FcCamera />
        {this.state.popupDesciption ? (
          <Modal
            isOpen={true}
            returnTo={new URL(location.href).pathname}
            handlerMouseLeave={this.mouseLeave}
            styles={{
              inset: "35% 0% 5% 46%",
              width: "38%",
              height: "50%",
              top: "25%",
              right: "20%",
              left: "50%",
              borderRadius: "5px 5px",
              fontFamily: "Gotham Pro, sans-serif !important",
              display: "flex",
              flexFlow: "column nowrap",
              fontSize: "16px",
              gap: "6%",
              padding: "10px 10px 10px 10px",
            }}>
            <TDescribeDishes
              src={src}
              dataRow={dataRow}
              addToCart={addToCart}
              cartItems={cartItems}
              mouseLeave={this.mouseLeave}
            />
          </Modal>
        ) : null}
      </td>
    );
  }
}

class TTable extends React.Component {
  constructor(props) {
    super(props);
  }
  render() {
    let { titleGroup, groupname, ColumnStruct, addToCart, cartItems } = this.props;
    let columnName = ColumnStruct("get");
    //columnName.map(name=>({title:name,disabled:groupname[`${titleGroup}`][0][`${name}`].disabled?"collapse":"visible"}));
    return (
      <div className='div_inventory'>
        <table className='inventory'>
          <caption style={{ align: "top", display: "flex" }}>{titleGroup}</caption>
          <colgroup>
            {columnName.map((el, i) => {
              let title = Object.keys(el)[0],
                obj = el[`${title}`];
              return (
                <col
                  id={title}
                  key={i}
                  style={{ visibility: obj.disabled ? "collapse" : "visible" }}
                />
              );
            })}
          </colgroup>
          <tbody>
            <tr>
              {columnName.map((el, i) => (
                <th
                  scope='col'
                  key={i}>
                  {Object.keys(el)[0]}
                </th>
              ))}
            </tr>
            {groupname[`${titleGroup}`].map((k, o) => {
              let dataRow = {};
              return (
                <tr key={o}>
                  {columnName.map((el, i) => {
                    let title = Object.keys(el)[0];
                    dataRow[`${title}`] = k[`${title}`][`${title}`];
                    if (title === "Описание") {
                      return (
                        <TDElement
                          key={i}
                          dataRow={dataRow}
                          src={k.PHOTO.src}
                          addToCart={addToCart}
                          cartItems={cartItems}
                        />
                      );
                    } else return <td key={i}>{dataRow[`${title}`]}</td>;
                  })}
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    );
  }
}

module.exports = TTable;

