sourcesContent:
const React = require("react");
const { Link } = require("react-router");

class Modal extends React.Component {
  constructor(props) {
    super(props);    
    this.styles = props.styles || {};        
    this.styles.width = this.styles.width || "75%";
    this.styles.height = this.styles.height || "90vh"; 
    this.styles.top = this.styles.top || "20%";     
    this.styles.left = this.styles.left || "1%";     
    this.styles.padding = this.styles.padding || "5px"; 
    this.styles.boxShadow = this.styles.boxShadow || "rgb(153, 153, 153) -3px -3px 0px 0px inset"; 
    this.styles.overflow = this.styles.overflow || "visible"; 
    this.styles.background = this.styles.background || "#ffff"; 
    this.styles.position = this.styles.position || "fixed";
    this.styles.overflowY = this.styles.overflowY || "hidden";
    this.CloseWnd = this.CloseWnd.bind(this);
    this.state = {CloseWnd:false};
  }
  CloseWnd(event){
   if (Object.hasOwn(this.props,"handlerMouseLeave")){
      this.props.handlerMouseLeave(event)
      this.setState({CloseWnd:true});
   }   
  }
  render() {
    return !this.state.CloseWnd?<div className="modal-wnd" style={this.styles}
            onMouseLeave={ this.CloseWnd }>
        <div className = "modal-wnd_main_wrapper" 
         style={{position:"relative", display:"flex", flexFlow:"column nowrap"}}
         >
         <p style={{
            display:"inline-block",
            position: "fixed",
            top: "21%", left: "6%"            
            }}
         >
            <Link 
             to={{
               pathname:this.props.returnTo, 
               state:{modal:false}
             }}  
             className="btn btn-primary"
            >Назад</Link>
         </p>
         {this.props.children}         
         </div>   
      </div>:
      null
   }
}

module.exports = Modal;

