sourcesContent:
const React = require("react");
const CchooseNumberPosition = require("./CchooseNumberPosition.jsx");
const { getBYN } = require("../js/formatFunction.js");
const { Link } = require("react-router");

/* окно описания товара */
class TDescribeDishes extends React.Component {
  constructor(props) {
    super(props);
    this.price = props.dataRow["Цена"];
    this.handleClick = this.handleClick.bind(this);

    let { cartItems } = props;
    let key = props.dataRow.RUID_ML;
    let count = Object.getOwnPropertyNames(cartItems)
      .filter((el) => el === key)
      .map((el) => cartItems[`${el}`].count)[0];
    this.state = { value: count === undefined ? 0 : count };
  }

  handleClick(event) {
    event.stopPropagation();
    event.preventDefault();
    let { value } = this.state;
    event.target.getAttribute("class") === "minus" ? --value : ++value;
    this.props.addToCart(this.props.dataRow, event.target.getAttribute("class"));
    this.setState({ value: value < 0 ? 0 : value });
  }

  render() {
    let { src, mouseLeave } = this.props;
    let describe = this.props.dataRow["Описание"];
    let dishes = this.props.dataRow["Изделие"];
    let sum = getBYN("*", this.price, this.state.value);
    return (
      <div
        className='section_boxes'
        style={{ display: "flex", flexFlow: "column" }}
        onMouseLeave={mouseLeave}>
        <p style={{ display: "inline-block" }}>{dishes}</p>
        <div style={{ display: "flex", flexFlow: "row norap" }}>
          <div className='modal-product-card__image-block'>
            {src !== undefined ? (
              <img
                src={src}
                style={{ width: "100%" }}
                alt='картинка блюда'
                className='medium'
              />
            ) : null}
          </div>
          <div className='group-item__image-container_describe'>
            <ul className='describeList'>
              {describe
                .split("_")
                .filter((dscr) => describe.length)
                .map((dscr, i) => (
                  <li
                    key={i}
                    style={{ listStyleType: "none" }}>
                    🌟 {dscr}
                  </li>
                ))}
            </ul>
          </div>
          <div className='tb_popup_zakaz'>
            <CchooseNumberPosition
              handler={this.handleClick}
              value={this.state.value}
            />
            <div
              className='final_sum'
              style={{ display: "flex", flexFlow: "column nowrap" }}>
              <span>{`Итого ${sum.RUB} руб. ${sum.KOP} коп.`}</span>
            </div>
          </div>
        </div>
      </div>
    );
  }
}

module.exports = TDescribeDishes;

