const React = require("react");

class CchooseNumberPosition extends React.Component{
   constructor(props){
      super(props);
   }
   render(){
      let {handler,value} = this.props;
      return( 
         <div className="choose_add_minus_value" style={{display:"flex", flexFlow:"row nowrap", justifyContent: "space-around", margin: "10px 0px"}}>            
            <div className="plus" onMouseDown={handler} style={{background:`url("../icons/add.png") top left no-repeat`, width:"46px", height:"46px"}}/>             
            <span className="kol_tov" style={{marginTop: "10px"}}>{value}</span>
            <div className="minus" onMouseDown={handler} style={{background:`url("../icons/minus.png") top left no-repeat`, width:"46px", height:"46px"}}/>            
         </div>)
   }
}

module.exports = CchooseNumberPosition;

