/* конвертировать вещественное значение, если там запятая в вещественное с точкой  */
const convertToNumeric = (val)=>{
   let regEx = /(?<coma>\,)/g;
   return val.replace(regEx, simb => {
    let s = '';
    switch (simb) {
      case ",": s = ".";            
    }
    return s;
   })
}

let getBYN = (type,...val)=>{
   let res = val.map(el=>convertToNumeric(String(el))).reduce((prev,cur)=> {
      switch (type){
         case "+": return  Math.fround(prev)+Math.fround(cur); 
         case "-": return Math.fround(prev)-Math.fround(cur);
         case "/": return prev/cur;
         case "*": return prev* cur;
      }
   })   
   let cop = /\.\d{1,2}/.exec(res);
   return cop === null?{RUB:Math.floor(res), KOP:0}:{RUB:Math.floor(res),KOP:Math.trunc(cop[0]*100)}
}

module.exports = {convertToNumeric,getBYN};

