sourcesContent:
const fs = require("fs");
const { stat } = require("fs/promises");
const colors = require("colors");

let historyChat = [];

async function InitHistoryChat() {
  let res = [];
  try {
    await stat("./chatHistory").then(async (Stats) => {
      console.log(JSON.stringify(Stats).bgRed);
      await fs.readFile("./chatHistory/chatHistory.txt", "utf8", (err, data) => {
        if (err) throw err;
        let reg = /\[end\]/gi;
        let messages = Buffer.from(data).toLocaleString();
        let match,
          index = -"[end]".length;
        console.log("Читаем чать".america, messages);

        while ((match = reg.exec(messages)) !== null) {
          let o = {};
          let cutWords = messages
            .substring(index + 5, match.index)
            .split(/(\[date\])|(\[table\])|(\[user\])|(\[to\])|(\[message\])/)
            .filter((el) => el)
            .filter((el, index) => index % 2);
          ["date", "table", "user", "to", "message"].forEach((val, index) => (o[`${val}`] = cutWords[index]));
          res.push(o);
          console.log(JSON.stringify(o).blue);
          index = match.index;
        }
      });
    });
  } catch (e) {
    console.log(e);
  }
  return res;
}

const getHistory = (user) =>
  historyChat.filter((message) => (message.user === user || message.to === user) && message.user !== message.to);

const deleteMessage = (user, table, item) => {
  let iterator = 0,
    numToDel;
  console.log("user", user);
  console.log("item", item);
  historyChat.map((obj, index) => {
    iterator++;
    if (obj.user === user && obj.table === table) {
      if (iterator === item) {
        numToDel = index;
      }
    }
    return obj;
  });

  historyChat.splice(numToDel, 1);
};

module.exports = { historyChat, InitHistoryChat, getHistory, deleteMessage };

