sourcesContent:
const fs = require("fs");
const { stat } = require("fs/promises");
const path = require("path");

(async function () {
  let hostsPath = path.join("c:/", "Windows", "System32", "drivers", "etc", "hosts");
  try {
    let stats = await stat(hostsPath);
    for (let [key, val] of Object.entries(stats)) {
      console.log(key, val);
    }
    fs.open(hostsPath, "r+", (err, fd) => {
      if (err) return console.error(err);
      let writable = fs.createWriteStream(null, { fd: fd, start: 10, defaultEncoding: "utf8" });
      writable.write("192.168.0.116   PositiveCheck");
    });
  } catch (e) {
    console.log("MISTAKE".bgMagenta);
  }
})();

