const path = require("path");
let fs = require("fs");
const fs_promise = fs.promises;
const { regExpClient } = require("../js/formatFunction.js");

async function readHearderPreOrder(pre_user, pre_table, pre_phone) {
  try {
    const files = await fs_promise.readdir(path.join(__dirname, "order"));
    for await (const file of files) {
      let dataBuffer = [];
      let stream = fs.createReadStream(file, "utf-8");
      stream.on("data", (chunk) => {
        dataBuffer = [...dataBuffer, chunk];
      });
      stream.on("end", () => {
        let { header } = JSON.parse(Buffer.from(dataBuffer).toJSON);

        let { user, table, phone } = header.reduce((prev, cur, i) => {
          if (!(i % 2)) {
            let k = {};
            k[`${cur}`] = header[i + 1];

            return { ...prev, ...k };
          } else {
            return { ...prev };
          }
        }, {});
      });
      if (user === pre_user && table === pre_table && phone === pre_phone) {
        return file;
      }
    }
    return undefined;
  } catch (err) {
    return undefined;
  }
}

module.exports = { readHearderPreOrder };

