const fs = require("fs");
const path = require("path");
const colors = require("colors");
const { unlink } = require("fs/promises");

// скрыть столик для других при предварительном заказе
async function disableTablePreOrder(tablkey) {
  let source = await require("./source/table.json");
  let { table } = source;
  console.log(JSON.stringify(table));
  source["table"] = Object.entries(
    Object.keys(table).reduce((prev, cur) => {
      prev[`${cur}`] = prev[`${cur}`].reduce((prevo, curo) => {
        return curo[`${tablkey}`] === undefined ? [...prevo, curo] : [...prevo];
      }, []);
      return prev;
    }, table)
  ).reduce((prev, cur) => {
    let [key, val] = cur;
    let o = {};
    o[`${key}`] = val;
    return val.length ? { ...prev, ...o } : { ...prev };
  }, {});
  console.log(JSON.stringify(source));
  await fs.promises.writeFile(path.join(__dirname, "source", "table.json"), JSON.stringify(source));
  return JSON.stringify(source);
}

function getNumberTableById(tablkey) {
  let table = require("../source/table.json");
  let result = {};
  for (let [key, val] of Object.entries(table)) {
    [...val].map((el) => {
      if (Object(el).hasOwnProperty(tablkey)) result[`${key}`] = el[`${tablkey}`];
    });
  }
  return result;
}

async function deleteOrder(folder) {
  try {
    let delete_order = require("../source/order_to_delete.json");
    console.log(delete_order);
    for await (let res of delete_order) {
      console.log("res", res.join().blue);
      let fileOrder = path.join(folder, "source", "order", `${res[0]}.json`);
      console.log("file".bgCyan, fileOrder.bgBlue);
      fs.stat(fileOrder, async (err, stats) => {
        if (err) return true;
        console.log(JSON.stringify(JSON.stringify(stats).bgMagenta));
        if (stats.isFile()) {
          let { header } = require(`${fileOrder}`);
          let { user, table, phone } = header.reduce((prev, cur) => ({ ...prev, ...cur }), {});
          let FileName_pre_order = path.join(folder, "source", "pre_order", `${table}_${phone}_${user}.json`);
          fs.stat(FileName_pre_order, async (err, stat) => {
            if (err) {
              return true;
            } else {
              if (stats.isFile()) {
                await unlink(FileName_pre_order);
              }
            }
          });
          await unlink(fileOrder);
        }
      });
    }
  } catch (err) {
    return true;
  }
}

// получить из списка столиков только тот столик, который сейчас в текущей сессии на фронте в объекте sessionStorage
// для того что бы вернуть на конкретный фронт только его с отметкой свободный и возможностью на том фронте в той сессии выбрать именно этот столик и никакой другой
function getTableInSessionStorage(sessionTable) {
  const { table } = require("../source/table.json");
  return [
    Object.entries(table).reduce((prev, [key, val]) => {
      let arr = val.filter((el) => Object.keys(el)[0] === sessionTable);
      if (arr.length) {
        let o = {};
        o[`${key}`] = Object.entries(arr[0])
          .map(([k, v]) => Object.defineProperty(arr[0], `${k}`, { value: v.replace(/\.\d+/, ".0") }))
          .flat()[0];

        return o;
      } else return { ...prev };
    }, {}),
  ];
}

module.exports = { deleteOrder, getTableInSessionStorage, disableTablePreOrder, getNumberTableById };

